begin transaction read only;
select jsonb_build_object('at',now(),'snapshots',jsonb_build_object('public.parties',(select jsonb_build_object('count',count(*),'fingerprint',md5(coalesce(string_agg(value,E'\n' order by value),''))) from (select (to_jsonb(t))::text value from public.parties t) s),'public.party_items',(select jsonb_build_object('count',count(*),'fingerprint',md5(coalesce(string_agg(value,E'\n' order by value),''))) from (select (to_jsonb(t))::text value from public.party_items t) s),'public.party_rsvps',(select jsonb_build_object('count',count(*),'fingerprint',md5(coalesce(string_agg(value,E'\n' order by value),''))) from (select (to_jsonb(t))::text value from public.party_rsvps t) s),'partyplus_private.host_access',(select jsonb_build_object('count',count(*),'fingerprint',md5(coalesce(string_agg(value,E'\n' order by value),''))) from (select (to_jsonb(t))::text value from partyplus_private.host_access t) s),'partyplus_private.memberships',(select jsonb_build_object('count',count(*),'fingerprint',md5(coalesce(string_agg(value,E'\n' order by value),''))) from (select (to_jsonb(t))::text value from partyplus_private.memberships t) s),'partyplus_private.operations',(select jsonb_build_object('count',count(*),'fingerprint',md5(coalesce(string_agg(value,E'\n' order by value),''))) from (select (to_jsonb(t))::text value from partyplus_private.operations t) s),'auth.users',(select jsonb_build_object('count',count(*),'fingerprint',md5(coalesce(string_agg(value,E'\n' order by value),''))) from (select (to_jsonb(t))::text value from auth.users t) s),'storage.objects',(select jsonb_build_object('count',count(*),'fingerprint',md5(coalesce(string_agg(value,E'\n' order by value),''))) from (select (to_jsonb(t))::text value from storage.objects t) s)),'access',jsonb_build_object('gate',(select writes_enabled from partyplus_private.release_control where singleton),'rpc',(select jsonb_agg(jsonb_build_object('function',p.oid::regprocedure::text,'role',r,'execute',has_function_privilege(r,p.oid,'EXECUTE')) order by p.oid::regprocedure::text,r) from pg_proc p join pg_namespace n on n.oid=p.pronamespace cross join (values('anon'),('authenticated')) roles(r) where n.nspname='public' and p.proname like 'partyplus_%'),'raw',(select jsonb_agg(jsonb_build_object('table',t,'role',r,'allowed',has_table_privilege(r,t,'SELECT,INSERT,UPDATE,DELETE,TRUNCATE,REFERENCES,TRIGGER')) order by t,r) from (values('anon'),('authenticated')) roles(r) cross join (values('public.parties'),('public.party_items'),('public.party_rsvps')) tables(t))),'installed',exists(select 1 from information_schema.columns where table_schema='public' and table_name='parties' and column_name='location_details')) as location_preflight;
rollback;
